const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const requesterId = parseInt(match[1], 10);
const body = $input.first().json.body || {};
const contactId = parseInt(body.id, 10);

if (!Number.isInteger(contactId)) throw new Error('"id" must be an integer.');

const accountId = (body.account_id === null || body.account_id === undefined || body.account_id === '')
  ? null
  : parseInt(body.account_id, 10);

if (accountId !== null && !Number.isInteger(accountId)) {
  throw new Error('"account_id" must be an integer or null.');
}

return [{
  json: {
    requesterId,
    contactId,
    first_name: (body.first_name ?? '').toString().trim(),
    last_name: (body.last_name ?? '').toString().trim(),
    job_title: (body.job_title ?? '').toString().trim(),
    account_id: accountId,
    email: (body.email ?? '').toString().trim(),
    secondary_email: (body.secondary_email ?? '').toString().trim(),
    phone: (body.phone ?? '').toString().trim(),
    secondary_phone: (body.secondary_phone ?? '').toString().trim(),
    linkedin_url: (body.linkedin_url ?? '').toString().trim(),
    lead_status: (body.lead_status ?? body.status ?? '').toString().trim(),
    lead_source: (body.lead_source ?? '').toString().trim(),
    city: (body.city ?? '').toString().trim(),
    state: (body.state ?? '').toString().trim(),
    zip_code: (body.zip_code ?? '').toString().trim(),
    country: (body.country ?? '').toString().trim(),
    do_not_contact: body.do_not_contact === undefined ? null : (body.do_not_contact === true || body.do_not_contact === 'true')
  }
}];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Contact not found or you do not have permission to edit it.');
}
return [{ json: { success: true, contact: result.json } }];
